<script setup lang="ts">import {computed} from 'vue';import type {FactorMetric} from '../types/domain';import {fixed} from '../utils/format';const props=defineProps<{rows:FactorMetric[],selected?:string}>();const emit=defineEmits<{select:[id:string]}>();const maxX=computed(()=>Math.max(...props.rows.map(r=>r.mu_star),.001)*1.18),maxY=computed(()=>Math.max(...props.rows.map(r=>r.sigma),.001)*1.25);const X=(v:number)=>60+v/maxX.value*460,Y=(v:number)=>275-v/maxY.value*225;</script><template><div class="morris-plot"><svg viewBox="0 0 580 335" role="img" aria-label="Morris平均绝对基本效应与样本离散图"><g v-for="t in [0,.25,.5,.75,1]" :key="t"><line x1="60" x2="520" :y1="Y(t*maxY)" :y2="Y(t*maxY)" class="grid-line"/><text x="8" :y="Y(t*maxY)+4">{{fixed(t*maxY,1)}}</text><text :x="X(t*maxX)" y="296" text-anchor="middle">{{fixed(t*maxX,0)}}</text></g><g v-for="r in rows" :key="r.factor_id" @click="emit('select',r.factor_id)" class="factor-dot"><circle :cx="X(r.mu_star)" :cy="Y(r.sigma)" :r="r.factor_id===selected?7:5"/><text :x="X(r.mu_star)+10" :y="Y(r.sigma)-7">{{r.factor_id}}</text><title>{{r.name}} · μ* {{fixed(r.mu_star)}} · σ {{fixed(r.sigma)}}</title></g><text x="290" y="325" text-anchor="middle">μ* / kWh·归一因子单位⁻¹</text><text x="60" y="25">σ / 同单位 · 样本ddof=1</text></svg><p class="plot-note">点选因子查看EE。μ*表示绝对影响，σ混合非线性与交互，不能单独区分二者。</p></div></template>
